SourceCode.Declaration:
/// <summary>
/// What the app needs to order an item: units, active dimensions, valid variants and the purchase order settings (minimum, maximum, multiple, standard quantity).
/// </summary>
[DataContractAttribute]
class HSMobileOpsOrderItem
{
    str itemId;
    str itemName;
    str purchUnit;
    str inventUnit;
    boolean configActive;
    boolean sizeActive;
    boolean colorActive;
    boolean styleActive;
    boolean batchActive;
    boolean serialActive;
    boolean negativePhysical;
    real minQty;
    real maxQty;
    real multipleQty;
    real standardQty;
    List variants;
}

Method.Source:
[DataMemberAttribute('ItemId')]
public str parmItemId(str _value = itemId)
{
    itemId = _value;
    return itemId;
}

